import{_ as a,o as e,c as s,a4 as d}from"./chunks/framework.BBs01uty.js";const u=JSON.parse('{"title":"Java 集合源码","description":"","frontmatter":{},"headers":[],"relativePath":"service/java-collections.md","filePath":"service/java-collections.md"}'),n={name:"service/java-collections.md"};function r(o,t,l,i,h,c){return e(),s("div",null,[...t[0]||(t[0]=[d(`<h1 id="java-集合源码" tabindex="-1">Java 集合源码 <a class="header-anchor" href="#java-集合源码" aria-label="Permalink to &quot;Java 集合源码&quot;">​</a></h1><blockquote><p><strong>优先级：P0（面试必考）</strong> — HashMap 原理是 Java 面试出镜率最高的题，没有之一。</p></blockquote><div class="tip custom-block"><p class="custom-block-title">背景</p><p>JS 开发者用 <code>{}</code>/<code>Map</code> 从不关心底层。Java 面试却要你把 HashMap 的数组、链表、红黑树、扩容讲清楚。本文用 JS 对照 + 面试考点组织。</p></div><h2 id="总览-集合体系" tabindex="-1">总览：集合体系 <a class="header-anchor" href="#总览-集合体系" aria-label="Permalink to &quot;总览：集合体系&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Collection（单列）</span></span>
<span class="line"><span>├── List（有序可重复）: ArrayList / LinkedList / Vector</span></span>
<span class="line"><span>├── Set（无序不可重复）: HashSet（底层 HashMap）/ LinkedHashSet / TreeSet</span></span>
<span class="line"><span>└── Queue: ArrayBlockingQueue / LinkedBlockingQueue</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Map（键值对）</span></span>
<span class="line"><span>├── HashMap（无序，最常用）</span></span>
<span class="line"><span>├── LinkedHashMap（插入序）</span></span>
<span class="line"><span>├── TreeMap（按 key 排序）</span></span>
<span class="line"><span>├── ConcurrentHashMap（线程安全）</span></span>
<span class="line"><span>└── Hashtable（线程安全，已过时）</span></span></code></pre></div><table tabindex="0"><thead><tr><th>JS</th><th>Java</th></tr></thead><tbody><tr><td><code>[]</code></td><td><code>ArrayList</code></td></tr><tr><td><code>{}</code> 字面量</td><td><code>HashMap</code></td></tr><tr><td><code>Set</code></td><td><code>HashSet</code></td></tr><tr><td><code>Object</code> 键</td><td><code>HashMap</code>（任意对象可作 key）</td></tr></tbody></table><h2 id="hashmap-原理-面试核心" tabindex="-1">HashMap 原理（面试核心） <a class="header-anchor" href="#hashmap-原理-面试核心" aria-label="Permalink to &quot;HashMap 原理（面试核心）&quot;">​</a></h2><h3 id="数据结构-数组-链表-红黑树" tabindex="-1">数据结构：数组 + 链表 + 红黑树 <a class="header-anchor" href="#数据结构-数组-链表-红黑树" aria-label="Permalink to &quot;数据结构：数组 + 链表 + 红黑树&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>数组 table[]（初始容量 16，2 的幂）</span></span>
<span class="line"><span>│</span></span>
<span class="line"><span>├─[0] → null</span></span>
<span class="line"><span>├─[1] → Node(key, value, hash) → Node → Node    // 链表（hash 冲突）</span></span>
<span class="line"><span>├─[2] → null</span></span>
<span class="line"><span>├─[3] → TreeNode ← TreeNode                     // 红黑树（链表 &gt; 8 且容量 ≥ 64）</span></span></code></pre></div><ul><li><strong>put 流程</strong>：<code>hash(key)</code> → 定位数组下标（<code>(n-1) &amp; hash</code>）→ 空则直接放 → 冲突则挂链表 → 链表长度 &gt; 8 且数组 ≥ 64 转红黑树</li><li><strong>get 流程</strong>：定位下标 → 遍历链表/树找 key 相同（<code>equals</code>）</li><li><strong>为什么用 2 的幂</strong>：<code>(n-1) &amp; hash</code> 等价取模，位运算比 <code>%</code> 快；扩容时位置要么不变要么 +oldCap</li></ul><h3 id="扩容-resize" tabindex="-1">扩容（resize） <a class="header-anchor" href="#扩容-resize" aria-label="Permalink to &quot;扩容（resize）&quot;">​</a></h3><ul><li>触发条件：<code>size &gt; 阈值</code>（阈值 = 容量 × 0.75 加载因子）</li><li>新容量 = 旧容量 × 2，<strong>重新计算所有元素位置</strong>（rehash，成本高）</li><li>为什么加载因子是 0.75：空间与时间折中——太高（如 1）链表长查询慢，太低（如 0.5）浪费空间</li></ul><h3 id="jdk-1-7-vs-1-8-对比-必考" tabindex="-1">JDK 1.7 vs 1.8 对比（必考） <a class="header-anchor" href="#jdk-1-7-vs-1-8-对比-必考" aria-label="Permalink to &quot;JDK 1.7 vs 1.8 对比（必考）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>差异</th><th>1.7</th><th>1.8</th></tr></thead><tbody><tr><td>数据结构</td><td>数组 + 链表</td><td>数组 + 链表 + 红黑树</td></tr><tr><td>插入方式</td><td><strong>头插法</strong></td><td><strong>尾插法</strong></td></tr><tr><td>扩容后 rehash</td><td>全部重算</td><td>优化：位置不变或 +oldCap</td></tr><tr><td>并发安全</td><td>扩容时<strong>可能死循环</strong>（头插法环链）</td><td>无死循环，但仍有数据丢失问题</td></tr></tbody></table><p><strong>1.7 头插法为什么死循环</strong>：多线程扩容时链表反转形成环。1.8 改尾插法修复，但 <strong>HashMap 仍然线程不安全</strong>，并发场景必须用 <code>ConcurrentHashMap</code>。</p><h2 id="concurrenthashmap-线程安全" tabindex="-1">ConcurrentHashMap（线程安全） <a class="header-anchor" href="#concurrenthashmap-线程安全" aria-label="Permalink to &quot;ConcurrentHashMap（线程安全）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>版本</th><th>并发控制</th></tr></thead><tbody><tr><td>1.7</td><td><strong>分段锁</strong>：数组分 16 段，每段一把锁，锁粒度粗</td></tr><tr><td>1.8</td><td><strong>CAS + synchronized</strong>：只锁链表头节点，粒度更细</td></tr></tbody></table><p>1.8 核心：插入时对目标桶的<strong>头节点</strong>加 <code>synchronized</code>（桶与桶之间并发），统计 size 用 CAS。读操作完全无锁（volatile 保证可见性）。</p><p><strong>面试题</strong>：ConcurrentHashMap 和 Hashtable 区别？——Hashtable 整表一把锁，所有操作串行，已淘汰；ConcurrentHashMap 锁粒度细 + CAS，并发性能高得多。</p><h2 id="arraylist-vs-linkedlist-高频" tabindex="-1">ArrayList vs LinkedList（高频） <a class="header-anchor" href="#arraylist-vs-linkedlist-高频" aria-label="Permalink to &quot;ArrayList vs LinkedList（高频）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>维度</th><th>ArrayList</th><th>LinkedList</th></tr></thead><tbody><tr><td>底层</td><td>动态数组</td><td>双向链表</td></tr><tr><td>随机访问 <code>get(i)</code></td><td><strong>O(1)</strong></td><td>O(n)</td></tr><tr><td>尾部插入</td><td>O(1)（均摊，扩容时 O(n)）</td><td>O(1)</td></tr><tr><td>中间插入/删除</td><td>O(n)（移动元素）</td><td>O(1)（找到节点后）</td></tr><tr><td>内存</td><td>连续，省内存</td><td>每个节点有前后指针，费内存</td></tr><tr><td>实际使用</td><td><strong>绝大多数场景用这个</strong></td><td>队列场景（Deque）</td></tr></tbody></table><p><strong>注意</strong>：<code>ArrayList</code> 扩容 = 新数组 = 1.5 倍旧容量 + 拷贝。<code>Arrays.asList()</code> 返回定长视图，不能 add/remove。</p><p><strong>高频题</strong>：ArrayList 和 LinkedList 什么时候用哪个？——随机访问多、尾部追加多用 ArrayList；频繁头尾操作（队列）用 LinkedList。实际业务 95% 用 ArrayList。</p><h2 id="常见面试陷阱" tabindex="-1">常见面试陷阱 <a class="header-anchor" href="#常见面试陷阱" aria-label="Permalink to &quot;常见面试陷阱&quot;">​</a></h2><table tabindex="0"><thead><tr><th>题</th><th>答案</th></tr></thead><tbody><tr><td>HashMap 初始容量为什么是 16</td><td>2 的幂，<code>(n-1) &amp; hash</code> 位运算定位</td></tr><tr><td>为什么负载因子 0.75</td><td>空间与时间折中</td></tr><tr><td>链表什么时候转红黑树</td><td>长度 &gt; 8 且容量 ≥ 64（先扩容，再转树）</td></tr><tr><td>红黑树什么时候退回链表</td><td>节点数 &lt; 6（防止频繁转换抖动）</td></tr><tr><td>自定义对象做 key 要注意什么</td><td>重写 <code>equals</code> 和 <code>hashCode</code>（否则同一内容对象查不到）</td></tr><tr><td>HashMap 允许 null 吗</td><td>key/value 都允许一个 null；ConcurrentHashMap 不允许</td></tr><tr><td>HashSet 怎么去重</td><td>底层是 HashMap，靠 equals + hashCode</td></tr></tbody></table><h2 id="延伸阅读" tabindex="-1">延伸阅读 <a class="header-anchor" href="#延伸阅读" aria-label="Permalink to &quot;延伸阅读&quot;">​</a></h2><ul><li><a href="/knowledge/service/java-concurrency.html">Java 并发编程</a> - ConcurrentHashMap 的 CAS/synchronized 背景</li><li><a href="/knowledge/service/java-basics.html">Java 入门（JS 开发者视角）</a> - 集合使用基础</li><li><a href="/knowledge/service/spring-principles.html">Spring 核心原理</a> - 单例 Bean 容器也是 Map 结构</li></ul>`,27)])])}const b=a(n,[["render",r]]);export{u as __pageData,b as default};
